#include "codegen_internal.h"

/**
 * @brief Write the function-qualified label for a basic block.
 *
 * @param out Target output stream.
 * @param fn_name Name of the function owning the block.
 * @param block_id ID of the block whose label is emitted.
 */
static void cg_print_block_label(FILE* out, char* fn_name, size_t block_id) {
  fprintf(out, "$%s$b%zu", fn_name, block_id);
}

// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Find a single-use comparison at the branch it feeds.
IrInstruction* cg_branch_comparison(IrFunction* fn,
                                    IrBlock* block,
                                    const size_t* uses) {
  IrInstructionArray* instructions = &block->instructions;
if (block->terminator.type != IR_TERMINATOR_CONDITIONAL ||
      instructions->count == 0)
    return NULL;

  IrOperand condition = block->terminator.value.conditional_target.condition;
  IrInstruction* last = &instructions->data[instructions->count - 1];
if (condition.type != IR_OP_VALUE || last->result != condition.value.id ||
      uses[last->result] != 1 || cg_ordered_inclusive(fn, last))
    return NULL;

  switch (last->type) {
    case IR_INST_EQ:
    case IR_INST_NE:
    case IR_INST_LE:
    case IR_INST_GE:
      return last;
    default:
      return NULL;
  }
}

void cg_generate_block(Ctx* ctx,
                       FILE* out,
                       const CgPlacement* placement,
                       IrFunction* fn,
                       size_t block_id,
                       IrBlockId next_block,
                       IrBlock* block,
                       IrInstruction* comparison,
                       bool direct_entry) {
  fputs("LABEL ", out);
  cg_print_block_label(out, fn->name, block_id);
  cg_print_nl(out);

  for (size_t i = 0; i < block->instructions.count; i++) {
    IrInstruction* inst = &block->instructions.data[i];
    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Implement all"
    // Changes: Let the branch emit its own comparison.
    if (inst != comparison && !cg_elides_copy(inst, placement))
      cg_generate_instruction(ctx, out, placement, fn, inst);
  }

  switch (block->terminator.type) {
    case IR_TERMINATOR_EXIT:
      fputs("EXIT ", out);
      cg_print_operand(out, placement, &block->terminator.value.exit_code);
      cg_print_nl(out);
      break;
    case IR_TERMINATOR_JUMP:
      // AI generated by: Codex (GPT-6.2-sol)
      // Prompt: "Implement all"
      // Changes: Skip jumps to the next emitted block.
      if (block->terminator.value.jump_target != IR_INVALID_ID &&
          block->terminator.value.jump_target != next_block) {
        fputs("JUMP ", out);
        cg_print_block_label(out, fn->name,
                             block->terminator.value.jump_target);
        cg_print_nl(out);
      }
      break;
    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Implement all"
    // Changes: Exit directly from an entrypoint that has no callers.
    case IR_TERMINATOR_RETURN:
      if (direct_entry) {
        fputs("EXIT int@0\n", out);
        break;
      }
      // AI generated by: Codex (GPT-6.2-sol)
      // Prompt: "Implement all"
      // Changes: Push the return operand without a frame result variable.
      if (fn->return_type != IR_UNIT) {
        IrFunctionId fid = (IrFunctionId)(fn - ctx->ir.functions.data);
        fputs(cg_uses_stack_return(ctx, fid) ? "PUSHS " : "MOVE LF@%ret ", out);
        cg_print_operand(out, placement, &block->terminator.value.return_value);
        cg_print_nl(out);
      }
      fputs("POPFRAME", out);
      cg_print_nl(out);
      fputs("RETURN", out);
      cg_print_nl(out);
      break;
    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Implement all"
    // Changes: Use the adjacent successor as fallthrough when possible.
    case IR_TERMINATOR_CONDITIONAL: {
      IrBlockId yes = block->terminator.value.conditional_target.true_target;
      IrBlockId no = block->terminator.value.conditional_target.false_target;
      // Invert the test when the true edge can use fallthrough.
      bool invert = yes == next_block;
      // AI generated by: Codex (GPT-6.2-sol)
      // Prompt: "Implement all"
      // Changes: Fuse equality branches and absorb inclusive predicate
      // inversion.
      bool unequal = invert;
if (comparison &&
          (comparison->type == IR_INST_NE || comparison->type == IR_INST_GE ||
           comparison->type == IR_INST_LE))
        unequal = !unequal;
      bool direct = comparison && (comparison->type == IR_INST_EQ ||
                                   comparison->type == IR_INST_NE);
      if (comparison && !direct) {
        cg_print_binary_inst(out, placement,
                             comparison->type == IR_INST_GE ? "LT" : "GT",
                             comparison);
      }
      fputs(unequal ? "JUMPIFNEQ " : "JUMPIFEQ ", out);
      cg_print_block_label(out, fn->name, invert ? no : yes);
      cg_print_ws(out);
      if (direct) {
        cg_print_operand(out, placement, &comparison->operands.binary.left);
        cg_print_ws(out);
        cg_print_operand(out, placement, &comparison->operands.binary.right);
        cg_print_nl(out);
      } else {
        cg_print_operand(out, placement,
                         &block->terminator.value.conditional_target.condition);
        fputs(" bool@true\n", out);
      }
      if (!invert && no != next_block) {
        fputs("JUMP ", out);
        cg_print_block_label(out, fn->name, no);
        cg_print_nl(out);
      }
      break;
    }
  }
}
